java.util.List<net.coobird.thumbnailator.filters.ImageFilter> myFilters = java.util.Arrays.asList(
    new net.coobird.thumbnailator.filters.ImageFilter() {
        @Override
        public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
            java.awt.image.BufferedImage out = new java.awt.image.BufferedImage(
                img.getWidth(), img.getHeight(), java.awt.image.BufferedImage.TYPE_INT_ARGB);
            java.awt.Graphics2D g = out.createGraphics();
            g.setColor(java.awt.Color.RED);
            g.fillRect(0, 0, img.getWidth(), img.getHeight());
            g.dispose();
            return out;
        }
    },
    new net.coobird.thumbnailator.filters.ImageFilter() {
        @Override
        public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
            java.awt.image.BufferedImage out = new java.awt.image.BufferedImage(
                img.getWidth(), img.getHeight(), java.awt.image.BufferedImage.TYPE_INT_ARGB);
            java.awt.Graphics2D g = out.createGraphics();
            g.drawImage(img, 0, 0, null);
            g.setColor(java.awt.Color.BLUE);
            g.fillRect(0, 0, img.getWidth() / 2, img.getHeight());
            g.dispose();
            return out;
        }
    }
);

